const currentScene = game.scenes.active;
const otherScenes = game.scenes.filter(s=>s.uuid !== currentScene?.uuid).map(s => ({ value: s.id, label: s.name, group: s.folder?.name ?? "" }));
const contentTemplate = Handlebars.compile(`
          <div class="form-group">
            <label for="scene">Scene</label>
            <select name="scene">
              {{selectOptions otherScenes localize=true}}
            </select>
          </div>
`);

const doorSource = await game.modules.get("dylans-general-automations").api.scripts.UserPaintArea();

if (!doorSource) return;

const sceneId = await new Promise(async (resolve)=>{
  foundry.applications.api.DialogV2.wait({
    window: { title: 'Select Scene' },
    content: contentTemplate({otherScenes}),
    buttons: [{
      action: "ok",
      label: "OK",
      default: true,
      callback: (event, button, dialog) => resolve(button.form.elements.scene?.value ?? null),
    }],
    close: () => resolve(null),
  }).catch(()=>{
    resolve(null);
  });
});

if (!sceneId) return;
const otherScene = game.scenes.get(sceneId);
if (!otherScene) return;

await otherScene.view();
const doorDestination = await game.modules.get("dylans-general-automations").api.scripts.UserPaintArea();
if (!doorDestination) return;

// create the document
const doorData = {
    "elevation": {
        "bottom": 0,
        "top": 20,
        "topInclusive": false
    },
    "levels": [
        "defaultLevel0000"
    ],
    "restriction": {
        "enabled": false,
        "type": "move",
        "priority": 0
    },
    "attachment": {
        "token": null
    },
    "visibility": CONST.REGION_VISIBILITY.LAYER,
    "highlightMode": "shapes",
    "displayMeasurements": false,
    "hidden": false,
    "name": `Door to ${otherScene.name}`,
    "shapes": [
        {
            "type": "rectangle",
            "x": doorSource.x,
            "y": doorSource.y,
            "width": currentScene.grid.size,
            "height": currentScene.grid.size,
            "hole": false,
            "anchorX": 0,
            "anchorY": 0,
            "rotation": 0,
            "gridBased": false
        }
    ],
    "behaviors": [{
        "name": "Door",
        "type": "dylans-general-automations.door",
        "system": {
            "destinationSceneId": otherScene.id,
            "destinationPosition": {
                "x": doorDestination.x,
                "y": doorDestination.y
            }
        },
        "disabled": false,
        "flags": {},
    }
],
    "locked": false,
};
await currentScene.createEmbeddedDocuments("Region", [doorData]);

await currentScene.view();
